#[cfg(test)]
mod continuation_tests {
    use super::super::continuation_storage::{Frame, Storage};
    use super::*;
    use crate::bounded_output::with_limit_usage_refusal;
    use crate::test_allocation_observer::measure;
    #[test]
    fn ordinary_factored_functions_and_contracts_reuse_exact_program_storage_with_old_automata_work_and_drop(
    ) {
        let decisions = (0..13)
            .map(|index| format!("let branch_{index}=if 0=={index} {{1}}else{{2}};"))
            .collect::<String>();
        let source = format!("module scratch.factored; @id(\"first\") fn first()->i64 requires 0==0 ensures result==42 {{{decisions}42}} @id(\"second\") fn second()->i64 requires 0==0 ensures result==42 {{{decisions}42}} @id(\"main\") fn main()->i64 requires 0==0 ensures result==42 {{{decisions}42}}");
        let program =
            crate::hir::resolve(&crate::check(&source, "factored-storage.spx").unwrap()).unwrap();
        let mut storage = Storage::new(&program);
        let mut old_budget = ReplayBudget::unobserved();
        let mut current_budget = ReplayBudget::unobserved();
        for function in &program.functions {
            assert!(selected(
                function,
                branch_sensitive_cfg_bounds(function)
                    .unwrap()
                    .terminal_paths,
                hir_terminal_path_bound(function).unwrap()
            ));
            let old = build_comparison(&program, function, &mut old_budget, None, None).unwrap();
            let current = build_comparison(
                &program,
                function,
                &mut current_budget,
                None,
                Some(&mut storage),
            )
            .unwrap();
            assert_eq!(
                (old.sink, old.hir_root, old.plan_root),
                (current.sink, current.hir_root, current.plan_root)
            );
            assert_eq!(old.automaton.nodes.len(), current.automaton.nodes.len());
            for (old, current) in old.automaton.nodes.iter().zip(&current.automaton.nodes) {
                assert_eq!(old.moves, current.moves);
                assert_eq!(old.epsilon, current.epsilon);
            }
            assert!(
                storage.frames.is_some(),
                "top-level continuation lease returned"
            );
            assert!(storage.frames.as_ref().unwrap().is_empty());
        }
        assert_eq!(old_budget.remaining, current_budget.remaining);
        assert_eq!(old_budget.skeleton_spent, current_budget.skeleton_spent);
        // Actual ordinary factored admission, rather than only a direct producer.
        for function in &program.functions {
            assert!(validate_with_index_storage(
                &program,
                function,
                &mut current_budget,
                None,
                Some(&mut storage)
            )
            .unwrap());
        }
        drop(storage);
        let observe = |limit, pooled| {
            with_limit_usage_refusal(limit, || {
                measure(|| {
                    let mut budget = ReplayBudget::new();
                    let mut storage = Storage::new(&program);
                    let mut success = true;
                    for function in &program.functions {
                        let result = build_comparison(
                            &program,
                            function,
                            &mut budget,
                            None,
                            if pooled { Some(&mut storage) } else { None },
                        );
                        if result.is_err() {
                            success = false;
                            assert!(budget.reserve_bytes(function, 0, "retry").is_err());
                        }
                        drop(result);
                        if !success {
                            break;
                        }
                    }
                    assert!(
                        storage.frames.is_some(),
                        "top-level continuation lease returned"
                    );
                    drop(storage);
                    drop(budget);
                    success
                })
            })
        };
        let ((old_success, old), old_refused, old_charge, _) = observe(usize::MAX, false);
        let ((success, current), refused, required, _) = observe(usize::MAX, true);
        assert!(old_success && success && !old_refused && !refused);
        // Three functions each evaluate requires/body/ensures: nine original
        // independent 516-frame buffers, versus one retained invocation buffer.
        let removed = 8 * 516 * std::mem::size_of::<Frame<'_>>();
        assert_eq!(old.allocated - current.allocated, removed);
        assert_eq!(old.allocations - current.allocations, 8);
        assert_eq!(old_charge - required, removed);
        assert!(!old.invalid && !current.invalid);
        assert_eq!((old.live, current.live), (0, 0));
        assert_eq!(old.allocated, old.freed);
        assert_eq!(current.allocated, current.freed);
        let ((success, exact), refused, charged, _) = observe(required, true);
        assert!(success && !refused && charged == required && !exact.invalid && exact.live == 0);
        let ((success, short), refused, _, receipt) = observe(required - 1, true);
        assert!(!success && refused && receipt.is_some() && !short.invalid && short.live == 0);
        assert_eq!(short.allocated, short.freed);
    }
}

//! Admission is independent of the actual allocation payer. An active builder
//! does not grant any selected schema, helper lease or replay shortcut.
use super::*;
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum AdmissionMode {
    Ordinary,
    SelectedRetained,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum AllocationPayer {
    LegacyUnobserved,
    ActiveBuilder,
    SelectedReservation,
}
pub(super) fn set_key<K: Ord + ClonePayload>(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    set: &BTreeSet<K>,
    key: &K,
) -> Result<(), Diagnostic> {
    if !set.contains(key) {
        budget.reserve_btree_node::<K, ()>(function, "ordinary identity tree")?;
    }
    budget.reserve_clone(function, key, "ordinary identity clone")
}
pub(super) fn insert_id(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    set: &mut BTreeSet<DeclarationId>,
    key: &DeclarationId,
) -> Result<bool, Diagnostic> {
    set_key(function, budget, set, key)?;
    Ok(set.insert(key.clone()))
}
pub(super) fn leaf_payload(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    storage: &StorageId,
    projections: &Vec<DeclarationId>,
    lifecycle: &DeclarationId,
) -> Result<(), Diagnostic> {
    budget.reserve_clone(function, storage, "ordinary leaf storage")?;
    budget.reserve_clone(function, projections, "ordinary leaf projections")?;
    budget.reserve_clone(function, lifecycle, "ordinary leaf lifecycle")
}
pub(super) fn leaf_indexes(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    leaves: &BTreeMap<LivenessFlagId, Leaf>,
    places: &BTreeSet<CleanupPlace>,
    flag: LivenessFlagId,
    leaf: &Leaf,
) -> Result<(), Diagnostic> {
    if !leaves.contains_key(&flag) {
        budget.reserve_btree_node::<LivenessFlagId, Leaf>(function, "ordinary leaf index")?;
    }
    budget.reserve_clone(function, &leaf.place, "ordinary leaf clone")?;
    budget.reserve_clone(function, &leaf.lifecycle, "ordinary leaf lifecycle clone")?;
    if !places.contains(&leaf.place) {
        budget.reserve_btree_node::<CleanupPlace, ()>(function, "ordinary leaf places")?;
    }
    Ok(())
}
impl ReplayBudget {
    #[cfg(test)]
    pub(super) fn unobserved() -> Self {
        Self {
            payer: AllocationPayer::LegacyUnobserved,
            ..Self::new()
        }
    }

    pub(super) fn new() -> Self {
        Self {
            admission: AdmissionMode::Ordinary,
            payer: if crate::bounded_output::active_limit().is_some() {
                AllocationPayer::ActiveBuilder
            } else {
                AllocationPayer::LegacyUnobserved
            },
            remaining: MAX_REPLAY_WORK_UNITS,
            skeleton_remaining: 0,
            skeleton_spent: 0,
            lent_skeleton: false,
            merge_paths: false,
            physical: None,
            refusal_text: None,
            refusal_spent: false,
            builder_clone_cursor_paid: false,
        }
    }
    #[cfg(test)]
    pub(super) fn with_skeleton_limit(limit: usize) -> Self {
        Self {
            admission: AdmissionMode::Ordinary,
            payer: if crate::bounded_output::active_limit().is_some() {
                AllocationPayer::ActiveBuilder
            } else {
                AllocationPayer::LegacyUnobserved
            },
            remaining: MAX_REPLAY_WORK_UNITS,
            skeleton_remaining: limit,
            skeleton_spent: 0,
            lent_skeleton: false,
            merge_paths: false,
            physical: None,
            refusal_text: None,
            refusal_spent: false,
            builder_clone_cursor_paid: false,
        }
    }

    pub(super) fn selected(&self) -> bool {
        self.admission == AdmissionMode::SelectedRetained
    }
    pub(super) fn pays_allocations(&self) -> bool {
        self.payer != AllocationPayer::LegacyUnobserved
    }
    /// The fixed type-clone census cursor is shared across clone preflights;
    /// pay its exact stack layout before any preflight can initialize it.
    pub(super) fn prepare_clone_cursor(
        &mut self,
        function: &ResolvedFunction,
    ) -> Result<(), Diagnostic> {
        if self.payer == AllocationPayer::ActiveBuilder && !self.builder_clone_cursor_paid {
            self.reserve_array::<Option<(&ResolvedType, usize)>>(
                function,
                514,
                "ordinary clone census cursor",
            )?;
            self.builder_clone_cursor_paid = true;
        }
        Ok(())
    }

    /// Reserve the first refusal's backing on the existing builder before any
    /// replay allocation. Initial refusal is inline, never an unfunded string.
    pub(super) fn prepare_builder(
        &mut self,
        function: &ResolvedFunction,
    ) -> Result<(), Diagnostic> {
        if self.payer != AllocationPayer::ActiveBuilder {
            return Ok(());
        }
        if self.refusal_spent || crate::bounded_output::active_refused() {
            return Err(self.budget_refusal(function, "ordinary builder already failed", ""));
        }
        let Some(capacity) = function.id.as_str().len().checked_add(512) else {
            return Err(self.budget_refusal(
                function,
                "ordinary replay refusal layout overflowed",
                "",
            ));
        };
        if self
            .refusal_text
            .as_ref()
            .is_some_and(|text| text.capacity() >= capacity)
        {
            return Ok(());
        }
        // A later function may have a longer current ID. Charge its new
        // complete backing while the earlier buffer is still held.
        if !crate::bounded_output::reserve_active_required(capacity) {
            return Err(self.budget_refusal(
                function,
                "ordinary replay refusal reservation exhausted",
                "",
            ));
        }
        let text = String::with_capacity(capacity);
        if text.capacity() != capacity {
            return Err(self.budget_refusal(
                function,
                "ordinary replay refusal capacity differs",
                "",
            ));
        }
        self.refusal_text = Some(text);
        Ok(())
    }
}

